import sys
import math
from collections import deque

def dijkstra(start, end, max_speed, wind1, wind2, t):
    queue = deque([start])
    dist = {start: 0}

    while queue:
        current = queue.popleft()
        if current == end:
            return dist[current]

        cx, cy, ct = current
        if ct < t:
            next_wind = wind1
        else:
            next_wind = wind2

        for dx in range(-max_speed, max_speed + 1):
            for dy in range(-max_speed, max_speed + 1):
                if dx**2 + dy**2 > max_speed**2:
                    continue

                nx, ny = cx + dx + next_wind[0], cy + dy + next_wind[1]
                nt = ct + 1
                new_dist = dist[current] + 1

                if (nx, ny, nt) not in dist or dist[(nx, ny, nt)] > new_dist:
                    dist[(nx, ny, nt)] = new_dist
                    queue.append((nx, ny, nt))

    return float('inf')

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    x1, y1, x2, y2 = map(int, data[:4])
    max_speed, t = map(int, data[4:6])
    wind1 = tuple(map(int, data[6:8]))
    wind2 = tuple(map(int, data[8:10]))

    start = (x1, y1, 0)
    end = (x2, y2, float('inf'))

    result = dijkstra(start, end, max_speed, wind1, wind2, t)
    print(result)

if __name__ == "__main__":
    main()
